import{_ as c,o as s,c as u}from"./chunks/framework.BnuTGVYS.js";const r=JSON.parse('{"title":"Linux 常用系统状态查看命令","titleTemplate":":title · 知行笔记","description":"查看系统、CPU、内存、磁盘、进程、网络、服务和日志的常用命令。部分命令需要 sudo 权限或额外安装工具。 执行前，将示例中的 IP 192.0.2.10 、PID、服务名和目录替换为实际值。 安装可选查看工具：iostat、lsof、n","frontmatter":{"title":"Linux 常用系统状态查看命令","titleTemplate":":title · 知行笔记","description":"查看系统、CPU、内存、磁盘、进程、网络、服务和日志的常用命令。部分命令需要 sudo 权限或额外安装工具。 执行前，将示例中的 IP 192.0.2.10 、PID、服务名和目录替换为实际值。 安装可选查看工具：iostat、lsof、n","kb":"{\\"site\\":{\\"title\\":\\"知行笔记\\",\\"description\\":\\"把实践整理成知识，让经验随时可查。\\",\\"publicRepository\\":\\"alcq77/alcq77.github.io\\",\\"localOnly\\":false,\\"support\\":{\\"wechat\\":\\"assets/support/wechat.jpg\\",\\"alipay\\":\\"assets/support/alipay.jpg\\"}},\\"docs\\":[{\\"id\\":\\"docker-compose-operations-commands\\",\\"title\\":\\"Docker 与 Docker Compose 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kafka-operations\\",\\"title\\":\\"Kafka 部署、运维与故障排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-internals\\",\\"title\\":\\"Kafka 核心机制与源码排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-reliability\\",\\"title\\":\\"Kafka 消息生产、消费与可靠性实践\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kubernetes-operations-commands\\",\\"title\\":\\"Kubernetes 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-cluster-troubleshooting\\",\\"title\\":\\"Kubernetes 集群搭建、维护与故障排查\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-application-practice\\",\\"title\\":\\"Kubernetes 应用部署与配置实践\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"linux-system-status-commands\\",\\"title\\":\\"Linux 常用系统状态查看命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-service-check-start-troubleshooting\\",\\"title\\":\\"Linux 服务检查、启动与排障\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-systemd-autostart\\",\\"title\\":\\"Linux 服务开机自启与 systemd 管理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-server-operations-commands\\",\\"title\\":\\"Linux 服务器常用运维命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-kernel-troubleshooting\\",\\"title\\":\\"Linux 内核问题排查与处理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-performance-troubleshooting\\",\\"title\\":\\"Linux 性能瓶颈排查与优化\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"nginx-operations\\",\\"title\\":\\"Nginx 配置、部署与日常运维\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"}],\\"doc\\":{\\"id\\":\\"linux-system-status-commands\\",\\"title\\":\\"Linux 常用系统状态查看命令\\",\\"category\\":\\"Linux 运维\\"},\\"content\\":\\"\\\\u003cdiv class=\\\\\\"article-head\\\\\\">\\\\u003cdiv class=\\\\\\"eyebrow\\\\\\">Linux 运维\\\\u003c/div>\\\\u003ch1>Linux 常用系统状态查看命令\\\\u003c/h1>\\\\u003cdiv class=\\\\\\"article-meta\\\\\\">\\\\u003cspan class=\\\\\\"author-avatar\\\\\\">知\\\\u003c/span>\\\\u003cspan>知行笔记\\\\u003c/span>\\\\u003cspan class=\\\\\\"meta-dot\\\\\\">·\\\\u003c/span>\\\\u003cspan>约 9 分钟阅读\\\\u003c/span>\\\\u003c/div>\\\\u003cdiv class=\\\\\\"tag-row\\\\\\">\\\\u003cspan class=\\\\\\"tag\\\\\\">linux\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">operations\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">network\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">troubleshooting\\\\u003c/span>\\\\u003c/div>\\\\u003c/div>\\\\u003carticle class=\\\\\\"markdown-body\\\\\\">\\\\u003cp>查看系统、CPU、内存、磁盘、进程、网络、服务和日志的常用命令。部分命令需要 sudo 权限或额外安装工具。\\\\u003c/p>\\\\n\\\\u003cp>执行前，将示例中的 IP \\\\u003ccode>192.0.2.10\\\\u003c/code>、PID、服务名和目录替换为实际值。\\\\u003c/p>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>安装可选查看工具：iostat、lsof、nc、dig\\\\u003c/summary>\\\\n\\\\u003cp>先执行 \\\\u003ccode>cat /etc/os-release\\\\u003c/code> 确认系统。仅安装缺少的包，普通用户需有sudo授权。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Ubuntu / Debian\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get update\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install sysstat lsof netcat-openbsd dnsutils\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>sysstat\\\\u003c/code>提供 \\\\u003ccode>iostat/pidstat\\\\u003c/code>，\\\\u003ccode>netcat-openbsd\\\\u003c/code>提供 \\\\u003ccode>nc\\\\u003c/code>，\\\\u003ccode>dnsutils\\\\u003c/code>提供 \\\\u003ccode>dig/nslookup\\\\u003c/code>。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 使用dnf的RHEL系\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> dnf install sysstat lsof nmap-ncat bind-utils\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>CentOS 7按现有批准仓库安装：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> yum install sysstat lsof nmap-ncat bind-utils \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 安装CPU/磁盘、文件、TCP及DNS查看工具\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>nc\\\\u003c/code>来自nmap-ncat，参数以 \\\\u003ccode>nc -h\\\\u003c/code> 为准；sysstat旧版本的列名可能不同，按表头阅读，不按固定列号取值。仓库失效处理见\\\\u003ca href=\\\\\\"linux-server-operations-commands.html\\\\\\">服务器常用命令\\\\u003c/a>，不要换成新版系统源。安装后验证：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v iostat lsof nc dig\\\\niostat -V\\\\nnc -h\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>基础命令包缺失、更多工具及旧系统说明见 \\\\u003ca href=\\\\\\"linux-server-operations-commands.html\\\\\\">服务器常用命令\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003ch2 id=\\\\\\"1-系统信息与运行时间\\\\\\">1. 系统信息与运行时间\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /etc/os-release   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 系统发行版\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -a              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 内核版本、主机架构等\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">date\\\\u003c/span>                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前日期、时间与时区\\\\u003c/span>\\\\ntimedatectl           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 时间、时区和同步状态\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uptime\\\\u003c/span>                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 运行时长、登录人数、平均负载\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uptime\\\\u003c/span> -s             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 最近一次开机时间\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>uptime\\\\u003c/code> 显示 \\\\u003ccode>up 23 days\\\\u003c/code>，表示已连续运行约23天。末尾 \\\\u003ccode>load average: 0.20, 0.35, 0.40\\\\u003c/code> 分别为最近1、5、15分钟平均负载，不能当作20%、35%、40%的 CPU 使用率。负载需结合 CPU 核数、CPU 占用和 I/O 等待判断。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"2-cpu与实时监控\\\\\\">2. CPU与实时监控\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">nproc\\\\u003c/span>                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前进程可用的处理器数量\\\\u003c/span>\\\\nlscpu                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># CPU型号、架构、逻辑CPU等\\\\u003c/span>\\\\ntop                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实时查看CPU、内存和进程\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>nproc\\\\u003c/code> 输出 \\\\u003ccode>8\\\\u003c/code>，表示当前进程可用的处理器数量为8。容器或资源限制可能使其与整台机器的逻辑 CPU 数不同。\\\\u003ccode>top\\\\u003c/code> 中可观察哪个进程的 \\\\u003ccode>%CPU\\\\u003c/code> 或 \\\\u003ccode>%MEM\\\\u003c/code> 较高。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"top怎么退出\\\\\\">top怎么退出\\\\u003c/h3>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>按键\\\\u003c/th>\\\\n\\\\u003cth>效果\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>q\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>退出 top\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>\\\\u003ccode>Ctrl+C\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003ctd>通常也可退出 top\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>\\\\u003cstrong>两种方式都只是结束监控界面，不会停止被查看的进程或服务。\\\\u003c/strong> 这是在前台运行 top 时的行为，不要将其他命令中的 Ctrl+C 理解为也不会影响其运行。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"3-内存swap与系统采样\\\\\\">3. 内存、Swap与系统采样\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">free -h               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 内存与Swap，按易读单位显示\\\\u003c/span>\\\\nvmstat 1 5            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 每秒采样一次，共输出5次\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>free -h\\\\u003c/code> 中 \\\\u003ccode>available\\\\u003c/code> 为 \\\\u003ccode>5.2Gi\\\\u003c/code>，表示估计还有约5.2GiB可供新应用使用。判断内存余量优先看 \\\\u003ccode>available\\\\u003c/code>，不要只看 \\\\u003ccode>free\\\\u003c/code>，因为部分缓存可回收。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>vmstat 1 5\\\\u003c/code> 第一行通常是开机以来的平均值，后续行反映采样期间的变化。\\\\u003ccode>si/so\\\\u003c/code> 持续较高可提示 Swap 换入换出活跃；\\\\u003ccode>wa\\\\u003c/code> 较高可提示 I/O 等待，但仍需结合其他指标分析。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"4-查找进程与资源占用\\\\\\">4. 查找进程与资源占用\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># CPU占用最高的前10个进程，包含一行表头\\\\u003c/span>\\\\nps -eo pid,ppid,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">comm\\\\u003c/span>,%cpu,%mem --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sort\\\\u003c/span>=-%cpu | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 11\\\\n\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 内存占用最高的前10个进程\\\\u003c/span>\\\\nps -eo pid,ppid,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">comm\\\\u003c/span>,%cpu,%mem --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sort\\\\u003c/span>=-%mem | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 11\\\\n\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查找命令行含java的进程\\\\u003c/span>\\\\npgrep -af java\\\\n\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看指定进程的父进程、启动时间、运行时长、状态及完整参数\\\\u003c/span>\\\\nps -ww -p 15164 -o pid,ppid,lstart,etime,\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">stat\\\\u003c/span>,args\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：若实际 PID 为24680，把最后一条中的 \\\\u003ccode>15164\\\\u003c/code> 换为 \\\\u003ccode>24680\\\\u003c/code>。\\\\u003ccode>etime\\\\u003c/code> 是运行时长，\\\\u003ccode>lstart\\\\u003c/code> 是启动时间，\\\\u003ccode>ppid\\\\u003c/code> 是父进程ID。\\\\u003ccode>ps\\\\u003c/code> 的 \\\\u003ccode>%CPU\\\\u003c/code> 通常反映进程生命周期内的 CPU 使用比例，不是与 top 完全相同的即时采样。\\\\u003c/p>\\\\n\\\\u003cp>按路径搜索不到进程时，可换进程名查询，例如 \\\\u003ccode>pgrep -af node-red\\\\u003c/code>；程序可能改写进程标题。需要同时核对监听端口的进程归属。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"5-磁盘分区与目录占用\\\\\\">5. 磁盘、分区与目录占用\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -h                            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 各文件系统的容量和剩余空间\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -i                            \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># inode使用情况\\\\u003c/span>\\\\nlsblk -f                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 磁盘、分区、文件系统及挂载点\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">du\\\\u003c/span> -sh /var/log                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定目录的总占用\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">du\\\\u003c/span> -h --max-depth=1 . | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sort\\\\u003c/span> -h    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前目录下一层占用，按大小升序\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>df -h\\\\u003c/code> 显示 \\\\u003ccode>/\\\\u003c/code> 使用率95%，再按具体目录执行 \\\\u003ccode>du\\\\u003c/code> 定位大目录。\\\\u003ccode>du -sh /var/log\\\\u003c/code> 返回 \\\\u003ccode>2.3G /var/log\\\\u003c/code>，表示日志目录占约2.3GB。若空间未满却无法创建文件，继续检查 \\\\u003ccode>df -i\\\\u003c/code> 是否 inode 耗尽。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003cstrong>df看文件系统是否满，du找目录占用。\\\\u003c/strong> 大目录扫描可能较慢，先查具体目录；没有权限读取的内容会影响 du 的统计完整性。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>du ... | sort -h\\\\u003c/code> 中的 \\\\u003ccode>|\\\\u003c/code> 是管道，把左边的目录占用结果交给右边排序；\\\\u003ccode>sort -h\\\\u003c/code> 能识别K、M、G等大小单位。同理，\\\\u003ccode>ps ... | head -n 11\\\\u003c/code> 表示只显示前11行（通常含一行表头），不会修改进程。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"6-ip路由端口和连接\\\\\\">6. IP、路由、端口和连接\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">ip -br addr                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 简洁显示网卡、状态和IP\\\\u003c/span>\\\\nip route                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 路由与默认网关\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># TCP监听端口及进程\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lnup                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># UDP端口及进程\\\\u003c/span>\\\\nss -s                             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 套接字状态汇总\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;sport = :1880&#x27;\\\\u003c/span>      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 指定TCP监听端口\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>ss\\\\u003c/code> 显示 \\\\u003ccode>*:1880\\\\u003c/code>、\\\\u003ccode>pid=15164\\\\u003c/code>，可据此核对该端口所属进程。若显示 \\\\u003ccode>127.0.0.1:1880\\\\u003c/code>，则仅监听本机回环地址，外部无法直接通过网卡地址访问。查8080时，把最后一条的1880换成8080。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"7-网络连通性与http响应\\\\\\">7. 网络连通性与HTTP响应\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">ping -c 4 192.0.2.10\\\\nnc -vz -w 3 192.0.2.10 8080\\\\ncurl -I --connect-timeout 3 --max-time 5 http://127.0.0.1:1880/\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：替换服务器IP后，第一条发送4次 Ping，第二条尝试连接8080端口，第三条检查本机1880的 HTTP HEAD 响应。\\\\u003ccode>nc\\\\u003c/code> 需已安装，选项以本机实现为准。\\\\u003c/p>\\\\n\\\\u003cul>\\\\n\\\\u003cli>Ping不通可能是禁用ICMP；Ping通不代表应用端口可用。\\\\u003c/li>\\\\n\\\\u003cli>TCP连通不代表认证或业务功能正常。\\\\u003c/li>\\\\n\\\\u003cli>返回200表示该请求成功；401、403、404等也说明收到了HTTP响应，需继续核对路径、权限和响应来源。\\\\u003c/li>\\\\n\\\\u003cli>接口不支持HEAD时，用 \\\\u003ccode>curl -i URL\\\\u003c/code> 对已确认的只读GET接口验证。\\\\u003c/li>\\\\n\\\\u003c/ul>\\\\n\\\\u003ch2 id=\\\\\\"8-系统服务与日志\\\\\\">8. 系统服务与日志\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">systemctl --failed\\\\nsystemctl list-units --\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">type\\\\u003c/span>=service --state=running\\\\nsystemctl status sshd --no-pager -l\\\\njournalctl -u sshd -n 100 --no-pager\\\\njournalctl --since \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;1 hour ago&quot;\\\\u003c/span> --no-pager\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k -b --no-pager\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>systemctl --failed\\\\u003c/code> 列出失败单元；\\\\u003ccode>status sshd\\\\u003c/code> 查看SSH服务状态；\\\\u003ccode>journalctl -u sshd\\\\u003c/code> 查看它最近100条日志。服务名因系统不同可能是 \\\\u003ccode>ssh\\\\u003c/code>，应使用实际名称。日志是否完整取决于权限和保留策略。\\\\u003c/p>\\\\n\\\\u003cp>最后一条中的 \\\\u003ccode>-k\\\\u003c/code> 表示内核日志，\\\\u003ccode>-b\\\\u003c/code> 表示本次开机。手动通过 nohup 启动的程序不一定有对应 systemd 服务单元，需查询它实际重定向的日志文件。\\\\u003c/p>\\\\n\\\\u003cp>查看文件日志：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span> -n 100 /var/log/messages\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">tail\\\\u003c/span> -F /var/log/messages\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：第一条读取最后100行，第二条持续跟踪，并在轮转后尝试继续跟踪同名文件。\\\\u003ccode>Ctrl+C\\\\u003c/code> 只退出 tail，不会停止产生日志的服务。部分系统没有 \\\\u003ccode>/var/log/messages\\\\u003c/code>，可使用 journalctl；应用日志则替换为实际路径。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"9-登录重启与oom记录\\\\\\">9. 登录、重启与OOM记录\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">w\\\\nlast -n 10\\\\nlast -x -F | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">head\\\\u003c/span> -n 20\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k -b --no-pager |\\\\n  grep -Ei \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;out of memory|oom-kill|killed process&#x27;\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>w\\\\u003c/code> 查看当前登录会话；\\\\u003ccode>last\\\\u003c/code> 查看历史登录；\\\\u003ccode>last -x\\\\u003c/code> 包含重启和关机记录。若内核日志出现 \\\\u003ccode>Killed process 12345 (node)\\\\u003c/code> 等OOM记录，应结合时间、PID和应用日志判断是否是目标服务。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>| grep ...\\\\u003c/code> 将左侧日志的标准输出交给 \\\\u003ccode>grep\\\\u003c/code> 过滤，不会自动包含标准错误。示例在 \\\\u003ccode>|\\\\u003c/code> 后换行，仍属于同一条管道命令，不是两次独立执行。\\\\u003c/p>\\\\n\\\\u003cp>查不到记录不等于没发生过：日志可能没有保留，且这里的OOM命令只查本次开机。登录记录也不能单独证明某个用户停止了服务。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"10-日常先记住这8条\\\\\\">10. 日常先记住这8条\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uptime\\\\u003c/span>                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 运行时间与平均负载\\\\u003c/span>\\\\ntop                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实时CPU与进程；q或Ctrl+C退出\\\\u003c/span>\\\\nfree -h                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 内存，重点看available\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -h                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 文件系统空间\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -i                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># inode\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># TCP监听端口及进程\\\\u003c/span>\\\\nsystemctl --failed     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 失败单元\\\\u003c/span>\\\\njournalctl -n 100       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 最近100条系统日志\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：发现访问变慢，先用 \\\\u003ccode>uptime\\\\u003c/code>、\\\\u003ccode>top\\\\u003c/code>、\\\\u003ccode>free -h\\\\u003c/code> 查看负载和资源，再用 \\\\u003ccode>ss\\\\u003c/code> 确认端口、用日志定位错误，不要直接重启全部服务。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"相关文档\\\\\\">相关文档\\\\u003c/h2>\\\\n\\\\u003cul>\\\\n\\\\u003cli>\\\\u003ca href=\\\\\\"linux-service-check-start-troubleshooting.html\\\\\\">Linux 服务检查、启动与排障\\\\u003c/a>：进一步排查服务不可访问、绑定地址、防火墙和启动问题。\\\\u003c/li>\\\\n\\\\u003c/ul>\\\\n\\\\u003c/article>\\\\u003cdiv class=\\\\\\"article-end\\\\\\">\\\\u003cspan>— 本文结束 —\\\\u003c/span>\\\\u003ca href=\\\\\\"../index.html\\\\\\">返回知识库首页 ↗\\\\u003c/a>\\\\u003c/div>\\",\\"toc\\":[{\\"title\\":\\"1. 系统信息与运行时间\\",\\"level\\":2,\\"id\\":\\"1-系统信息与运行时间\\"},{\\"title\\":\\"2. CPU与实时监控\\",\\"level\\":2,\\"id\\":\\"2-cpu与实时监控\\"},{\\"title\\":\\"top怎么退出\\",\\"level\\":3,\\"id\\":\\"top怎么退出\\"},{\\"title\\":\\"3. 内存、Swap与系统采样\\",\\"level\\":2,\\"id\\":\\"3-内存swap与系统采样\\"},{\\"title\\":\\"4. 查找进程与资源占用\\",\\"level\\":2,\\"id\\":\\"4-查找进程与资源占用\\"},{\\"title\\":\\"5. 磁盘、分区与目录占用\\",\\"level\\":2,\\"id\\":\\"5-磁盘分区与目录占用\\"},{\\"title\\":\\"6. IP、路由、端口和连接\\",\\"level\\":2,\\"id\\":\\"6-ip路由端口和连接\\"},{\\"title\\":\\"7. 网络连通性与HTTP响应\\",\\"level\\":2,\\"id\\":\\"7-网络连通性与http响应\\"},{\\"title\\":\\"8. 系统服务与日志\\",\\"level\\":2,\\"id\\":\\"8-系统服务与日志\\"},{\\"title\\":\\"9. 登录、重启与OOM记录\\",\\"level\\":2,\\"id\\":\\"9-登录重启与oom记录\\"},{\\"title\\":\\"10. 日常先记住这8条\\",\\"level\\":2,\\"id\\":\\"10-日常先记住这8条\\"},{\\"title\\":\\"相关文档\\",\\"level\\":2,\\"id\\":\\"相关文档\\"}],\\"standaloneTitle\\":\\"\\"}"},"headers":[],"relativePath":"articles/linux-system-status-commands.md","filePath":"articles/linux-system-status-commands.md"}'),n={name:"articles/linux-system-status-commands.md"};function e(a,l,t,o,p,d){return s(),u("div")}const h=c(n,[["render",e]]);export{r as __pageData,h as default};
